import units from '../../vendor/isa-phm-specification/catalogues/qudt-units-3.5.2.json';

// QUDT 3.5.2, CC BY 4.0, https://qudt.org/; generated by
// scripts/generate_unit_catalogue.py. Deprecated or unlabelled entries are omitted.
export const UNIT_CATALOGUE_VERSION = 'qudt-3.5.2';
export const UNIT_CATALOGUE = Object.freeze(units);
const unitsByIdentifier = new Map(UNIT_CATALOGUE.map((unit) => [unit.identifier, unit]));

// Do not guess from a symbol: different units can share one, and legacy
// projects may not have an identifier at all.
export const formatUnit = (value = '', identifier = '') => {
  const unit = unitsByIdentifier.get(identifier);
  return unit && unit.symbol === value ? `${value} (${unit.name})` : value;
};

export const searchUnits = (query = '', quantity = '') => {
  const exactSearch = query.trim();
  const search = exactSearch.toLocaleLowerCase();
  const normalizedQuantity = quantity.trim().toLocaleLowerCase();
  const score = (unit) => {
    const terms = [unit.symbol, unit.name, ...unit.aliases].map((item) => item.toLocaleLowerCase());
    if (!search) return 0;
    // Symbols can be case-sensitive: g (gram) and G (gravity) differ.
    if (unit.symbol === exactSearch) return 4;
    if (terms.some((term) => term === search || term.replace(/^\[|\]$/g, '') === search)) return 3;
    if (terms.some((term) => term.split(/[^\p{L}\p{N}]+/u).includes(search))) return 2;
    return terms.some((term) => term.startsWith(search)) ? 1 : 0;
  };
  return UNIT_CATALOGUE.filter((unit) => `${unit.symbol} ${unit.name} ${unit.identifier} ${unit.aliases.join(' ')}`.toLocaleLowerCase().includes(search))
    .sort((a, b) => score(b) - score(a)
      || Number(b.quantities.some((kind) => kind.toLocaleLowerCase() === normalizedQuantity)) - Number(a.quantities.some((kind) => kind.toLocaleLowerCase() === normalizedQuantity))
      || a.name.localeCompare(b.name));
};

export const unitSelection = (identifier) => {
  const unit = unitsByIdentifier.get(identifier);
  return unit ? { value: unit.symbol, valueIdentifier: unit.identifier } : null;
};
